title Order State Machine Diagram

[*] --> Created : New Order Placed

state Created {
  [*] --> WaitingForPayment
}

state Paid {
  [*] --> PaymentConfirmed
}

state Shipped {
  [*] --> InTransit
}

state Delivered {
  [*] --> OrderComplete
}

state Cancelled {
  [*] --> OrderTerminated
}

Created --> Paid : Payment Received
Created --> Cancelled : Order Cancelled by User/System

Paid --> Shipped : Order Dispatched
Paid --> Cancelled : Order Cancelled before Dispatch

Shipped --> Delivered : Package Delivered

Delivered --> [*]
Cancelled --> [*]

@enduml

