workspace {
    model {
        customer = person "Customer" {
            description "A person who orders food through the platform."
        }

        courier = person "Courier" {
            description "A person who delivers food to customers."
        }

        mapsService = softwareSystem "Maps Service" {
            description "External maps and geolocation service."
            tags "External"
        }

        foodPlatform = softwareSystem "Food Delivery Platform" {
            description "Facilitates food ordering and delivery coordination."

            webApp = container "Web Frontend" {
                technology "React"
                description "Allows customers to browse restaurants and place orders, and couriers to accept deliveries."
            }

            api = container "API Gateway & Backend" {
                technology "Node.js"
                description "Handles business logic, user management, and order coordination."
            }

            database = container "Orders Database" {
                technology "PostgreSQL"
                description "Stores user profiles, restaurant menus, orders, and delivery status."
            }

            customer -> webApp "Browses menus and places orders"
            courier -> webApp "Views and accepts delivery requests"
            webApp -> api "Makes API calls"
            api -> database "Reads and writes data"
            api -> mapsService "Calculates routes and distances" "HTTPS"
        }
    }

    views {
        systemContext foodPlatform {
            include *
            autolayout lr
            title "System Context: Food Delivery Platform"
        }

        container foodPlatform {
            include *
            autolayout lr
            title "Container Diagram: Food Delivery Platform"
        }

        theme default
    }
}

workspace {

  model {
    operator = person "Operator" {
      description "Monitors IoT devices, telemetry, and system health."
    }

    iotDevices = softwareSystem "IoT Devices" {
      description "Edge sensors and physical devices sending telemetry data."
      tags "External"
    }

    iotPlatform = softwareSystem "IoT Monitoring Platform" {
      description "Ingests, processes, stores, and visualizes IoT telemetry data."

      ingestionService = container "Ingestion Service" {
        technology "Go / MQTT"
        description "Receives telemetry data streams from IoT devices."
      }

      messageBroker = container "Message Broker" {
        technology "Apache Kafka"
        description "Buffers and distributes incoming telemetry streams for processing."
      }

      streamProcessor = container "Stream Processor" {
        technology "Apache Flink"
        description "Reads telemetry events, performs real-time analytics and transformations."
      }

      timeSeriesDB = container "Time Series Database" {
        technology "InfluxDB"
        description "Stores high-volume time-series telemetry data."
      }

      dashboard = container "Dashboard Frontend" {
        technology "React / Grafana"
        description "Displays real-time charts, device health, and alerts to operators."
      }

      iotDevices -> ingestionService "Sends telemetry" "MQTT / HTTPS"
      ingestionService -> messageBroker "Publishes telemetry events"
      messageBroker -> streamProcessor "Streams events"
      streamProcessor -> timeSeriesDB "Writes processed metrics"
      dashboard -> timeSeriesDB "Queries telemetry data" "SQL / API"
    }

    operator -> iotPlatform "Views telemetry and alerts"
    iotDevices -> iotPlatform "Sends data"
  }

  views {
    systemContext iotPlatform {
      include *
      autolayout lr
      title "System Context: IoT Monitoring System"
    }

    container iotPlatform {
      include *
      autolayout lr
      title "Container Diagram: IoT Monitoring Platform"
    }

    theme default
  }
}

