digraph ThreeTierArchitecture {
    rankdir=LR;
    fontname="Helvetica";
    fontsize=14;

    node [shape=box, style="filled,rounded", fontname="Helvetica", fontsize=11, margin=0.2];
    edge [fontname="Helvetica", fontsize=9, color="#555555"];

    // Users
    Users [label="Users", shape=oval, style="filled", fillcolor="#e1f5fe"];

    subgraph cluster_presentation {
        label="Presentation Tier";
        style=dashed;
        color="#b0bec5";

        LB [label="Load Balancer", fillcolor="#fff9c4"];
    }

    subgraph cluster_web {
        label="Web Tier";
        style=dashed;
        color="#b0bec5";

        Web1 [label="Web Server 1", fillcolor="#c8e6c9"];
        Web2 [label="Web Server 2", fillcolor="#c8e6c9"];
    }

    subgraph cluster_application {
        label="Application Tier";
        style=dashed;
        color="#b0bec5";

        App [label="App Server", fillcolor="#ffe0b2"];
    }

    subgraph cluster_data {
        label="Data Tier";
        style=dashed;
        color="#b0bec5";

        Cache [label="Cache", fillcolor="#f8bbd0"];
        DB_Primary [label="Primary DB", fillcolor="#d1c4e9"];
        DB_Replica [label="Read Replica", fillcolor="#d1c4e9"];
    }

    // Connections
    Users -> LB [label="HTTPS"];
    LB -> Web1 [label="Route"];
    LB -> Web2 [label="Route"];

    Web1 -> App [label="RPC/HTTP"];
    Web2 -> App [label="RPC/HTTP"];

    App -> Cache [label="Read/Write"];
    App -> DB_Primary [label="Write"];
    App -> DB_Replica [label="Read"];

    DB_Primary -> DB_Replica [label="Replication", style=dotted];
}

