        description "Send telemetry and metrics data."
      }

      ingestionService = container "Ingestion Service" {
        technology "Go / MQTT Broker"
        description "Receives telemetry data from IoT devices."
      }

      streamProcessor = container "Stream Processor" {
        technology "Apache Kafka / Flink"
        description "Processes and transforms incoming telemetry streams."
      }

      timeSeriesDB = container "Time Series Database" {
        technology "TimescaleDB / InfluxDB"
        description "Stores high-throughput telemetry metrics."
      }

      dashboard = container "Dashboard Web App" {
        technology "React / TypeScript"
        description "Visualizes real-time metrics and alerts for operators."
      }

      devices -> ingestionService "Sends telemetry" "MQTT"
      ingestionService -> streamProcessor "Publishes raw data" "Kafka"
      streamProcessor -> timeSeriesDB "Writes processed metrics" "TCP"
      dashboard -> timeSeriesDB "Queries metrics" "SQL / HTTPS"
      operator -> dashboard "Views metrics and alerts" "HTTPS"
    }
  }

  views {
    systemContext iotSystem {
      include *
      autolayout lr
      title "System Context: IoT Monitoring System"
    }

    container iotSystem {
      include *
      autolayout lr
      title "Container Diagram: IoT Monitoring System"
    }

    theme default
  }
}

