digraph ThreeTierArchitecture {
    rankdir=LR;
    node [shape=box, style=filled, fontname="Arial", fontsize=12, fillcolor=lightblue];
    edge [fontname="Arial", fontsize=10];

    // External users
    users [label="Users", shape=ellipse, fillcolor=lightyellow];

    // Load Balancer tier
    lb [label="Load Balancer", fillcolor=orange];

    // Presentation tier (Web servers)
    subgraph cluster_web {
        label="Web Tier";
        style=filled;
        fillcolor=lightgray;
        web1 [label="Web Server 1"];
        web2 [label="Web Server 2"];
    }

    // Application tier
    subgraph cluster_app {
        label="Application Tier";
        style=filled;
        fillcolor=lightgray;
        app [label="App Server", fillcolor=lightgreen];
    }

    // Data tier
    subgraph cluster_data {
        label="Data & Caching Tier";
        style=filled;
        fillcolor=lightgray;
        cache [label="Cache", shape=cylinder, fillcolor=lightpink];
        primary_db [label="Primary Database", shape=cylinder, fillcolor=lightblue];
        replica_db [label="Read Replica", shape=cylinder, fillcolor=lightblue];
    }

    // Connections
    users -> lb [label="HTTPS"];
    lb -> web1 [label="Route"];
    lb -> web2 [label="Route"];

    web1 -> app [label="HTTP"];
    web2 -> app [label="HTTP"];

    app -> cache [label="Read/Write"];
    app -> primary_db [label="Write/Read"];
    app -> replica_db [label="Read Only"];

    primary_db -> replica_db [label="Replication", style=dashed];
}
